begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,auth;
select no_plan();
insert into auth.users(id,aud,role,email,raw_app_meta_data,raw_user_meta_data) values
('71111111-1111-4111-8111-111111111111','authenticated','authenticated','food-owner@local.test','{}','{}'),
('72222222-2222-4222-8222-222222222222','authenticated','authenticated','food-coach@local.test','{}','{}'),
('73333333-3333-4333-8333-333333333333','authenticated','authenticated','food-free@local.test','{}','{}');
update public.user_roles set role='coach' where user_id='72222222-2222-4222-8222-222222222222';
insert into public.user_subscriptions(user_id,plan_id,status,provider) select '71111111-1111-4111-8111-111111111111',id,'active','internal' from public.plans where code='premium';
insert into public.user_subscriptions(user_id,plan_id,status,provider) select '72222222-2222-4222-8222-222222222222',id,'active','internal' from public.plans where code='coach';
insert into public.coach_client_relationships(coach_user_id,client_user_id,status) values('72222222-2222-4222-8222-222222222222','71111111-1111-4111-8111-111111111111','active');
select is((public.claim_food_photo('74444444-4444-4444-8444-444444444444','71111111-1111-4111-8111-111111111111')->>'claimed')::boolean,true,'Premium can claim analysis');
select is((select count(*)::int from public.food_logs where user_id='71111111-1111-4111-8111-111111111111'),0,'Analysis claim creates no food logs');
select is((public.claim_food_photo('74444444-4444-4444-8444-444444444444','71111111-1111-4111-8111-111111111111')->>'claimed')::boolean,false,'Double-submit cannot claim twice');
select throws_ok($$select public.claim_food_photo('74444444-4444-4444-8444-444444444444','72222222-2222-4222-8222-222222222222')$$,'42501',null,'Cross-owner claim cannot reuse ID');
select throws_ok($$select public.claim_food_photo('75555555-5555-4555-8555-555555555555','73333333-3333-4333-8333-333333333333')$$,'42501',null,'Free blocked by database entitlement');
select is((public.claim_food_photo('76666666-6666-4666-8666-666666666666','72222222-2222-4222-8222-222222222222')->>'claimed')::boolean,true,'Coach may analyze own food');
select is((select public from storage.buckets where id='food-analysis'),false,'Food photo bucket private');
select is((select file_size_limit from storage.buckets where id='food-analysis'),3145728::bigint,'Storage upload limited to 3 MB');
select is((select allowed_mime_types from storage.buckets where id='food-analysis'),array['image/jpeg','image/png','image/webp'],'Storage image-only allowlist');
insert into storage.objects(bucket_id,name) values('food-analysis','71111111-1111-4111-8111-111111111111/74444444-4444-4444-8444-444444444444-1.jpg');
set local role authenticated;select set_config('request.jwt.claim.sub','71111111-1111-4111-8111-111111111111',true);
select is((select count(*)::int from public.food_photo_analyses),1,'Owner reads own analysis only');
select is((select count(*)::int from storage.objects where bucket_id='food-analysis'),1,'Owner reads exact linked photo path');
select throws_ok($$insert into public.food_photo_analyses(id,user_id) values(gen_random_uuid(),auth.uid())$$,'42501',null,'Normal client cannot insert arbitrary analysis');
select throws_ok($$update public.food_photo_analyses set status='confirmed'$$,'42501',null,'Normal client cannot mutate analysis');
select throws_ok($$select public.claim_food_photo(gen_random_uuid(),auth.uid())$$,'42501',null,'Normal client cannot invoke trusted claim');
select throws_ok($$select public.finish_food_photo('74444444-4444-4444-8444-444444444444',auth.uid(),1,null,'mock','mock','',true)$$,'42501',null,'Normal client cannot forge model output');
select throws_ok($$insert into storage.objects(bucket_id,name) values('food-analysis',auth.uid()::text||'/forged.jpg')$$,'42501',null,'Unvalidated direct photo upload blocked');
select set_config('request.jwt.claim.sub','72222222-2222-4222-8222-222222222222',true);
select is((select count(*)::int from public.food_photo_analyses where user_id='71111111-1111-4111-8111-111111111111'),0,'Coach relationship grants no client analysis access');
select is((select count(*)::int from storage.objects where bucket_id='food-analysis'),0,'Coach cannot read client photo');
select throws_ok($$select public.confirm_food_photo('74444444-4444-4444-8444-444444444444','[]','lunch',now())$$,'42501',null,'Cross-owner confirmation blocked');
reset role;
select set_config('qa.food_result','{"items":[{"name":"Rice","estimated_portion":{"amount":100,"unit":"g"},"estimated_calories":130,"protein_g":3,"carbs_g":28,"fat_g":0.3,"confidence":0.8}],"meal_totals":{"calories":130,"protein_g":3,"carbs_g":28,"fat_g":0.3},"uncertainties":["Portion approximate."]}',true);
select throws_ok($$select public.finish_food_photo('74444444-4444-4444-8444-444444444444','71111111-1111-4111-8111-111111111111',1,'{}','mock','fixture','',true)$$,'22023',null,'Missing structured items rejected by database');
select ok(public.finish_food_photo('74444444-4444-4444-8444-444444444444','71111111-1111-4111-8111-111111111111',1,current_setting('qa.food_result')::jsonb,'mock','fixture','',true),'Trusted result completes');
select is((select count(*)::int from public.food_logs where user_id='71111111-1111-4111-8111-111111111111'),0,'Completed analysis still creates no food logs');
select is((public.claim_food_photo('74444444-4444-4444-8444-444444444444','71111111-1111-4111-8111-111111111111',true)->>'claimed')::boolean,false,'Completed result reused even on retry');
set local role authenticated;select set_config('request.jwt.claim.sub','71111111-1111-4111-8111-111111111111',true);
select throws_ok($$select public.confirm_food_photo('74444444-4444-4444-8444-444444444444','[]','lunch',now())$$,'22023',null,'Empty review rejected');
select throws_ok($$select public.confirm_food_photo('74444444-4444-4444-8444-444444444444',current_setting('qa.food_result')::jsonb->'items','lunch',now()+interval '1 day')$$,'22023',null,'Future meal time rejected');
select is(cardinality(public.confirm_food_photo('74444444-4444-4444-8444-444444444444',jsonb_set(current_setting('qa.food_result')::jsonb->'items','{0,estimated_calories}','150'),'dinner',now(),'User corrected')),1,'Confirmed edited item creates one log');
select is((select calories from public.food_logs where user_id=auth.uid()),150::numeric,'Edited calories saved, not original model total');
select is((select meal_type::text from public.food_logs where user_id=auth.uid()),'dinner','Chosen meal type saved');
select is((select notes from public.food_logs where user_id=auth.uid()),'User corrected','Chosen notes saved');
select is((select food_id from public.food_logs where user_id=auth.uid()),null::uuid,'Snapshot does not create permanent food');
select is(cardinality(public.confirm_food_photo('74444444-4444-4444-8444-444444444444',current_setting('qa.food_result')::jsonb->'items','lunch',now())),1,'Repeated confirmation returns same identifiers');
select is((select count(*)::int from public.food_logs where user_id=auth.uid()),1,'Repeated confirmation creates no duplicate log');
select is((select calories from public.get_daily_nutrition((now() at time zone (select timezone from public.profiles where id=auth.uid()))::date)),150::numeric,'Existing nutrition aggregation includes confirmed snapshot');
reset role;
select ok(public.finish_food_photo('76666666-6666-4666-8666-666666666666','72222222-2222-4222-8222-222222222222',1,null,'mock','fixture','timeout',true),'Failure records safe code');
select is((public.claim_food_photo('76666666-6666-4666-8666-666666666666','72222222-2222-4222-8222-222222222222',true)->>'claimed')::boolean,true,'Explicit failed retry claims once');
select is(public.finish_food_photo('76666666-6666-4666-8666-666666666666','72222222-2222-4222-8222-222222222222',1,current_setting('qa.food_result')::jsonb,'mock','fixture','',true),false,'Stale attempt cannot overwrite newer retry');
select ok(public.finish_food_photo('76666666-6666-4666-8666-666666666666','72222222-2222-4222-8222-222222222222',2,null,'mock','fixture','timeout',true),'Second failure stored');
select public.claim_food_photo('76666666-6666-4666-8666-666666666666','72222222-2222-4222-8222-222222222222',true);
select public.finish_food_photo('76666666-6666-4666-8666-666666666666','72222222-2222-4222-8222-222222222222',3,null,'mock','fixture','timeout',true);
select throws_ok($$select public.claim_food_photo('76666666-6666-4666-8666-666666666666','72222222-2222-4222-8222-222222222222',true)$$,'54000',null,'Fourth attempt blocked');
update public.food_photo_analyses set expires_at=clock_timestamp()-interval '1 second' where user_id='71111111-1111-4111-8111-111111111111';
set local role authenticated;select set_config('request.jwt.claim.sub','71111111-1111-4111-8111-111111111111',true);
select is((select count(*)::int from public.food_photo_analyses),0,'Expired analysis inaccessible');
select is((select count(*)::int from storage.objects where bucket_id='food-analysis'),0,'Expired photo inaccessible');
reset role;
select ok(public.expire_food_photo('74444444-4444-4444-8444-444444444444','71111111-1111-4111-8111-111111111111'),'Cleanup expires cleared analysis');
select is((select result_json from public.food_photo_analyses where id='74444444-4444-4444-8444-444444444444'),null::jsonb,'Expiry purges structured details');
select * from finish();rollback;
